code='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] == 6 and grid[c][r] != 6:
                out[r][c] = grid[c][r]

    unresolved = [(r, c) for r in range(n) for c in range(len(grid[r]))
                  if grid[r][c] == 6 and grid[c][r] == 6]
    estimates = {}
    for r, c in unresolved:
        candidates = []
        known_row = [j for j, value in enumerate(grid[r]) if value != 6]
        for q in range(n):
            if q != r and grid[q][c] != 6:
                score = sum(grid[q][j] == grid[r][j] for j in known_row)
                if known_row:
                    candidates.append((score / len(known_row), score, grid[q][c]))
        known_col = [j for j in range(n) if grid[j][c] != 6]
        for q in range(n):
            if q != c and grid[r][q] != 6:
                score = sum(grid[j][q] == grid[j][c] for j in known_col)
                if known_col:
                    candidates.append((score / len(known_col), score, grid[r][q]))
        if candidates:
            estimates[(r, c)] = max(candidates)

    done = set()
    for r, c in unresolved:
        if (r, c) in done:
            continue
        choices = [estimates[k] for k in ((r, c), (c, r)) if k in estimates]
        if choices:
            value = max(choices)[2]
            out[r][c] = value
            out[c][r] = value
        done.add((r, c))
        done.add((c, r))
    return out
'''
